  values ('ME', 'essay', 'འོག་ལུ་བཀོད་ཡོད་པའི་དྲི་བ་གཉིས་ལས་ གཅིག་གདམ་ཁ་རྐྱབ་སྟེ་ ལན་ངེས་པར་དུ་བྲི་དགོ།

དྲི་བ་ཀ༽ སྤྱོད་འཇུག་ལེའུ་དང་པོའི་རྩ་བར། བྱང་ཆུབ་སེམས་དེ་མདོར་བསྡུས་ན། །རྣམ་པ་གཉིས་སུ་ཤེས་བྱ་སྟེ། །བྱང་ཆུབ་སྨོན་པའི་སེམས་དང་ནི། །བྱང་ཆུབ་འཇུག་པ་ཉིད་ཡིན་ནོ། །ཞེས་གསུངས་པའི་རྩ་ཚིག་གི་གོ་དོན་འགྲེལ་བཤད་བཅུད་བསྡུས་ཤིག་དང་། སེམས་བསྐྱེད་ངོ་བོའི་སྒོ་ནས་དབྱེ་བ་ཇི་ལྟར་ཡོད་པ། དབྱེ་བ་སོ་སོའི་མཚན་ཉིད། དབྱེ་བའི་ཁྱད་པར་བཅས་གསལ་པོར་བཀོད? (སྐུགས་ ༡༠)', 'ལན་གྱི་དཔེ་ (outline)
༡. གོ་དོན: བྱང་ཆུབ་ཀྱི་སེམས་མདོར་བསྡུ་ན་ རྣམ་པ་གཉིས་ཏེ་ བྱང་ཆུབ་སྨོན་པའི་སེམས་དང་ བྱང་ཆུབ་འཇུག་པའི་སེམས། རྩ་བ་རང་ལས་ "འགྲོ་བར་འདོད་དང་འགྲོ་བ་ཡི། །བྱེ་བྲག་ཇི་ལྟར་ཤེས་པ་ལྟར།" ཞེས་ ལམ་འགྲོ་བར་འདོད་པ་དང་ དངོས་སུ་འགྲོ་བ་ལྟར་ ཁྱད་པར་ཤེས་དགོས།
༢. ངོ་བོའི་སྒོ་ནས་དབྱེ་བ: ཀུན་རྫོབ་བྱང་ཆུབ་ཀྱི་སེམས་ (སྙིང་རྗེས་ཀུན་ནས་བསླང་སྟེ་ སེམས་ཅན་གྱི་དོན་དུ་ རྫོགས་བྱང་ཐོབ་འདོད་) དང་ དོན་དམ་བྱང་ཆུབ་ཀྱི་སེམས་ (སྟོང་ཉིད་མངོན་སུམ་དུ་རྟོགས་པའི་ཡེ་ཤེས་)། ཀུན་རྫོབ་སེམས་བསྐྱེད་ལ་ སྨོན་སེམས་དང་འཇུག་སེམས་གཉིས།
༣. མཚན་ཉིད: སྨོན་སེམས་ནི་ འགྲོ་བ་ཡོངས་ཀྱི་དོན་དུ་ སངས་རྒྱས་ཐོབ་པར་འདོད་པའི་ ཁས་ལེན་གྱི་སེམས། འཇུག་སེམས་ནི་ དེའི་ཆེད་དུ་ སྦྱིན་པ་ལ་སོགས་པའི་ ཕར་ཕྱིན་དྲུག་གི་སྤྱོད་པ་ལ་ དངོས་སུ་འཇུག་པའི་སེམས།
༤. ཁྱད་པར: སྨོན་སེམས་ལས་ འཁོར་བར་འབྲས་བུ་ཆེན་པོ་འབྱུང་ཡང་ བསོད་ནམས་རྒྱུན་ཆགས་སུ་མི་འབྱུང་། འཇུག་སེམས་བཟུང་བ་ཅིག་ལུ་ "ཉལ་བའམ་བག་མེད་གྱུར་ཀྱང་ བསོད་ནམས་ཤུགས་ནི་རྒྱུན་ཆད་མེད།" ཅེས་ བསོད་ནམས་རྒྱུན་ཆད་མེད་པར་འཕེལ།', null, '[{"point": "རྩ་ཚིག་གི་གོ་དོན་: བྱང་སེམས་ལ་ སྨོན་སེམས་དང་འཇུག་སེམས་གཉིས། དཔེ་ འགྲོ་བར་འདོད་པ་དང་འགྲོ་བ་ལྟར་ཁྱད་པར་ཤེས་དགོས་པ།", "marks": 3}, {"point": "ངོ་བོའི་སྒོ་ནས་དབྱེ་བ་: ཀུན་རྫོབ་བྱང་ཆུབ་ཀྱི་སེམས་དང་ དོན་དམ་བྱང་ཆུབ་ཀྱི་སེམས་གཉིས། ཀུན་རྫོབ་ལ་ སྨོན་འཇུག་གཉིས།", "marks": 2}, {"point": "མཚན་ཉིད་: སྨོན་སེམས་ = གཞན་དོན་དུ་རྫོགས་བྱང་ཐོབ་འདོད་ཀྱི་འདུན་པ། འཇུག་སེམས་ = དེའི་ཆེད་དུ་ཕར་ཕྱིན་དྲུག་གི་སྤྱོད་པ་ལ་དངོས་སུ་སློབ་པ།", "marks": 3}, {"point": "ཁྱད་པར་: སྨོན་སེམས་ལ་འབྲས་བུ་ཆེ་ཡང་ བསོད་ནམས་རྒྱུན་མི་འབྱུང་། འཇུག་སེམས་ལས་ ཉལ་བའམ་བག་མེད་གྱུར་ཀྱང་ བསོད་ནམས་ཤུགས་རྒྱུན་ཆད་མེད་པ་འཕེལ།", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'buddhist-studies'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'buddhist-studies') and t.slug = 'bodhicary-vat-ra'), (select id from public.exam_papers where code = 'me-dzongkha-3'), 'standard', 10,
    1080, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": ["Buddhist Studies: a lopen (Buddhist Studies teacher) must check the model answer and marking guide before publishing.", "Real RCSC text from a PDF whose font drops letters; repaired automatically: compare with the RCSC PDF."], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (Dzongkha category, Buddhist Studies): BCSE 2024, batch 1", "source": {"title": "BCSE 2024 Main Examination, Dzongkha category, Paper III (Buddhist Studies)", "year": 2024, "url": "https://rcsc.gov.bt/question-papers/"}}'::jsonb, null, null, null, null, null, null)
  returning id
