with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'essay', 'འོག་ལུ་བཀོད་ཡོད་པའི་དྲི་བ་གཉིས་ལས་ གཅིག་གདམ་ཁ་རྐྱབ་སྟེ་ ལན་ངེས་པར་དུ་བྲི་དགོ།

དྲི་བ་ཁ༽ དང་པོ་སྤྱོད་འཇུག་རྩ་བར། དལ་འབྱོར་འདི་ནི་རྙེད་པར་ཤིན་ཏུ་དཀའ། །སྐྱེས་བུའི་དོན་སྒྲུབ་ཐོབ་པར་གྱུར་པ་ལ། །གལ་ཏེ་འདི་ལ་ཕན་པ་མ་བསྒྲུབས་ན། །ཕྱིས་འདི་ཡང་དག་འབྱོར་བར་ག་ལ་འགྱུར། །ཞེས་གསུངས་པའི་གཞུང་དོན་ཇི་བཞིན་འགྲེལ་ནས། གཉིས་པ་དལ་འབྱོར་གྱི་མི་ལུས་འཐོབ་པར་རྒྱུའི་སྒོ་ནས་རྙེད་པར་དཀའ་ཚུལ་དང་། དཔེའི་སྒོ་ནས་རྙེད་པར་དཀའ་ཚུལ། གྲངས་ཀྱི་སྒོ་ནས་རྙེད་པར་དཀའ་ཚུལ་བཅས་རིམ་བཞིན་བྲིས? (སྐུགས་ ༡༠)', 'ལན་གྱི་དཔེ་ (outline)
༡. གཞུང་དོན: དལ་བ་བརྒྱད་དང་འབྱོར་པ་བཅུ་ལྡན་པའི་ མི་ལུས་རིན་པོ་ཆེ་འདི་ རྙེད་པར་ཤིན་ཏུ་དཀའ། འདི་གིས་ སྐྱེས་བུའི་དོན་ - མཐོ་རིས་དང་ ཐར་པ་ ཐམས་ཅད་མཁྱེན་པའི་གོ་འཕང་ - སྒྲུབ་ཚུགས། ད་རེས་ ཐོབ་པའི་སྐབས་འདི་ལུ་ ཕན་པ་མ་བསྒྲུབས་པ་ཅིན་ ཕྱིས་སུ་ ལུས་འདི་ལྟ་བུ་ཡང་དག་པར་འབྱོར་བ་ ག་ལ་འོང་ ཟེར་ བརྩོན་འགྲུས་བསྐྱེད་དགོས་པའི་གདམས་པ།
༢. རྒྱུའི་སྒོ་ནས་རྙེད་དཀའ: མི་ལུས་ཐོབ་པའི་རྒྱུ་ ཚུལ་ཁྲིམས་རྣམ་པར་དག་པ་ སྦྱིན་པ་ལ་སོགས་པའི་དགེ་བ་ དང་ སྨོན་ལམ་དག་པ་དགོས། དེ་ལྟར་སྒྲུབ་མི་ ཤིན་ཏུ་ཉུང་བས་ རྙེད་པར་དཀའ།
༣. དཔེའི་སྒོ་ནས་རྙེད་དཀའ: རྒྱ་མཚོ་ཆེན་པོ་ནང་ གཉའ་ཤིང་བུ་ག་ཅན་ཅིག་ རླུང་གིས་བསྐྱོད་དེ་ཡོད་པ་ལུ་ རུས་སྦལ་ལོང་བ་ཅིག་ ལོ་བརྒྱ་རེ་ཁར་ ཡར་ཐོན་ཏེ་ མགྲིན་པ་ བུ་ག་ནང་ཚུད་པ་ལྟར་ དཀོན། (སྲན་མ་ རྩིག་པར་འཕངས་ཏེ་ ཐོགས་པ་ལྟར་ ཟེར་ཡང་བཤད།)
