                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'long_answer', 'འོག་ལུ་བཀོད་ཡོད་པའི་དྲི་བ་ལྔ་ལས་ གང་རུང་གསུམ་ལུ་ལན་རྐྱབ།

དྲི་བ་ཁ༽ དང་པོ་སྙིང་རྗེ་རྣམ་པ་གསུམ་ངོས་ཟུངས? གཉིས་པ་སྙིང་རྗེ་གསུམ་གྱི་མཚན་ཉིད་དམ་ངོ་སྤྲོད་བཅུད་བསྡུས་རེ་བཀོད? གསུམ་པ་རྩ་བར། དང་པོར་ང་ཞེས་བདག་ལ་ཞེན་གྱུར་ཅིང་། །བདག་གི་འདི་ཞེས་དངོས་ལ་ཆགས་བསྐྱེད་པ། །ཟོ་ཆུན་འཕན་ལྟར་རང་དབང་མེད་པ་ཡི། །འགྲོ་ལ་སྙིང་རྗེར་གྱུར་གང་དེ་ལ་འདུད། །ཅེས་པའི་གཞུང་གིས་སྙིང་རྗེ་གསུམ་ལས་གང་བསྟན་པ་ཡིན་ནམ? བཞི་པ་སློབ་དཔོན་ཟླ་བས་དབུ་མ་འཇུག་པ་རྩོམ་དུས་ཐོག་མར་སྙིང་རྗེ་ལ་བསྟོད་ཕྱག་མཛད་དགོས་པའི་རྒྱུ་མཚན་སྙིང་བསྡུས་ཤིག་ཤོད? (སྐུགས་ ༡༢)', 'ལན་གྱི་དཔེ་ (outline)
༡. སྙིང་རྗེ་རྣམ་པ་གསུམ: སེམས་ཅན་ཙམ་ལ་དམིགས་པའི་སྙིང་རྗེ། ཆོས་ལ་དམིགས་པའི་སྙིང་རྗེ། དམིགས་པ་མེད་པའི་སྙིང་རྗེ།
༢. ངོ་སྤྲོད: (ཀ) སྡུག་བསྔལ་གྱིས་ཉེན་པའི་སེམས་ཅན་ཙམ་ལ་དམིགས་ཏེ་ སྡུག་བསྔལ་ལས་བྲལ་བར་འདོད་པ། (ཁ) སེམས་ཅན་དེ་ སྐད་ཅིག་རེ་ལུ་འཇིག་པའི་ མི་རྟག་པར་ཤེས་ཏེ་ སྙིང་རྗེ་བསྐྱེད་པ། (ག) སེམས་ཅན་ རང་བཞིན་གྱིས་མ་གྲུབ་པར་ (སྟོང་ཉིད་) ཤེས་བཞིན་དུ་ སྙིང་རྗེ་བསྐྱེད་པ།
༣. "དང་པོར་ང་ཞེས་བདག་ལ་ཞེན་གྱུར་ཅིང་..." རྩ་ཚིག་འདི་ ང་དང་ངའི་བར་ཞེན་ཏེ་ ཟོ་ཆུན་ལྟར་ རང་དབང་མེད་པར་ འཁོར་བར་འཁྱམས་པའི་ སེམས་ཅན་ལ་དམིགས་པའི་སྙིང་རྗེ་ བསྟན། (ཤུགས་ལ་ ཆོས་དང་དམིགས་མེད་ཀྱི་སྙིང་རྗེ་ཡང་ རྗེས་ཀྱི་ཚིག་ལས་བསྟན།)
༤. རྒྱུ་མཚན: སློབ་དཔོན་ཟླ་བ་གྲགས་པས་ "ལོ་ཐོག་ཕུན་ཚོགས་འདི་ཡི་ས་བོན་དང་། །སྤེལ་ལ་ཆུ་འདྲ་ཡུན་རིང་ལོངས་སྤྱོད་པའི། །གནས་སུ་སྨིན་འདྲར་འདོད་པ་..." ཞེས་ སྙིང་རྗེ་ནི་ ཐེག་ཆེན་གྱི་ ཐོག་མར་ ས་བོན་ བར་དུ་ ཆུ་ མཐར་ སྨིན་པའི་འབྲས་བུ་ ལྟར་ དུས་གསུམ་ཆར་ལུ་ གལ་ཆེ། སེམས་བསྐྱེད་དང་ གཉིས་མེད་བློ་ གཉིས་ཀྱི་ཡང་ རྩ་བ་ཨིནམ་ལས་ ཐོག་མར་ བསྟོད་པ་མཛད།', null, '[{"point": "སྙིང་རྗེ་གསུམ་: སེམས་ཅན་ལ་དམིགས་པ། ཆོས་ལ་དམིགས་པ། དམིགས་མེད།", "marks": 3}, {"point": "མཚན་ཉིད་ རེ་རེ་ (སྡུག་བསྔལ་གྱིས་གཟིར་བའི་སེམས་ཅན་ཙམ་ / མི་རྟག་པར་ / རང་བཞིན་མེད་པར་ ཤེས་ཏེ་ སྡུག་བསྔལ་ལས་བྲལ་བར་འདོད་པ)", "marks": 4}, {"point": "རྩ་ཚིག་འདིས་ སེམས་ཅན་ལ་དམིགས་པའི་སྙིང་རྗེ་ བསྟན།", "marks": 2}, {"point": "ཐོག་མར་སྙིང་རྗེ་ལ་བསྟོད་དགོས་པ་: ཐེག་ཆེན་གྱི་རྩ་བ། ཐོག་མར་ས་བོན་ བར་དུ་ཆུ་ མཐར་སྨིན་པའི་འབྲས་བུ་ལྟར་ གལ་ཆེ།", "marks": 3}]'::jsonb, (select id from public.subjects where slug = 'buddhist-studies'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'buddhist-studies') and t.slug = 'madhyamak-vat-ra-and-abhidharmako-a'), (select id from public.exam_papers where code = 'me-dzongkha-3'), 'standard', 12,
