  values ('ME', 'long_answer', 'འོག་ལུ་བཀོད་ཡོད་པའི་དྲི་བ་ལྔ་ལས་ གང་རུང་གསུམ་ལུ་ལན་རྐྱབ།

དྲི་བ་ག༽ དང་པོ་དབུ་མ་འཇུག་པའི་རྩ་བར། སྙིང་རྗེའི་སེམས་དང་གཉིས་སུ་མེད་བློ་དང་། །བྱང་ཆུབ་སེམས་ནི་རྒྱལ་སྲས་རྣམས་ཀྱི་རྒྱུ། །ཞེས་པའི་གཞུང་གི་དངོས་བསྟན་གང་སྟོན་པ་ཡིན་ནམ? གཉིས་པ་བྱང་སེམས་ཀྱི་མ་མཐའི་ས་མཚམས་སམ་མིང་འཕོ་བའི་ས་མཚམས་ངོས་ཟུངས? གསུམ་པ་བྱང་ཆུབ་སེམས་དཔའི་ས་བཅུ་དང་ལམ་ལྔ་གོ་རིམ་མ་ནོར་བར་བཀོད? (སྐུགས་ ༡༢)', 'ལན་གྱི་དཔེ་ (outline)
༡. དངོས་བསྟན: ཉན་རང་ནི་ ཐུབ་དབང་ལས་སྐྱེས། སངས་རྒྱས་ནི་ བྱང་ཆུབ་སེམས་དཔའ་ལས་འཁྲུངས། བྱང་ཆུབ་སེམས་དཔའ་ (རྒྱལ་སྲས་) ཀྱི་རྒྱུ་ནི་ སྙིང་རྗེའི་སེམས། གཉིས་སུ་མེད་པའི་བློ་ (ཡོད་མེད་ཀྱི་མཐའ་གཉིས་དང་བྲལ་བའི་ཤེས་རབ)། བྱང་ཆུབ་ཀྱི་སེམས་ དང་ གསུམ་ཨིན།
༢. ས་མཚམས: བཅོས་མ་མ་ཡིན་པའི་ བྱང་ཆུབ་ཀྱི་སེམས་ རྒྱུད་ལ་སྐྱེས་མ་ཐག་ ཐེག་ཆེན་ཚོགས་ལམ་ལུ་ཞུགས་ཏེ་ བྱང་ཆུབ་སེམས་དཔའ་ ཞེས་ མིང་འཕོ། (ས་དང་པོ་ མཐོང་ལམ་ལས་ འཕགས་པའི་བྱང་སེམས།)
༣. ས་བཅུ: རབ་ཏུ་དགའ་བ། དྲི་མ་མེད་པ། འོད་བྱེད་པ། འོད་འཕྲོ་བ། སྦྱང་དཀའ་བ། མངོན་དུ་གྱུར་པ། རིང་དུ་སོང་བ། མི་གཡོ་བ། ལེགས་པའི་བློ་གྲོས། ཆོས་ཀྱི་སྤྲིན།
༤. ལམ་ལྔ: ཚོགས་ལམ། སྦྱོར་ལམ། མཐོང་ལམ། སྒོམ་ལམ། མི་སློབ་ལམ།', null, '[{"point": "དངོས་བསྟན་: རྒྱལ་སྲས་ (བྱང་སེམས་) ཀྱི་རྒྱུ་ གསུམ་ - སྙིང་རྗེ། གཉིས་སུ་མེད་པའི་བློ། བྱང་ཆུབ་ཀྱི་སེམས།", "marks": 3}, {"point": "ས་མཚམས་: བྱང་ཆུབ་ཀྱི་སེམས་ (བཅོས་མ་མ་ཡིན་པ་) སྐྱེས་མ་ཐག་ ཚོགས་ལམ་ཐོབ་ སྟེ་ བྱང་ཆུབ་སེམས་དཔའ་ཞེས་ མིང་འཕོ།", "marks": 3}, {"point": "ས་བཅུ་: རབ་ཏུ་དགའ་བ། དྲི་མ་མེད་པ། འོད་བྱེད་པ། འོད་འཕྲོ་བ། སྦྱང་དཀའ་བ། མངོན་དུ་གྱུར་པ། རིང་དུ་སོང་བ། མི་གཡོ་བ། ལེགས་པའི་བློ་གྲོས། ཆོས་ཀྱི་སྤྲིན།", "marks": 4}, {"point": "ལམ་ལྔ་: ཚོགས་ལམ། སྦྱོར་ལམ། མཐོང་ལམ། སྒོམ་ལམ། མི་སློབ་ལམ།", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'buddhist-studies'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'buddhist-studies') and t.slug = 'madhyamak-vat-ra-and-abhidharmako-a'), (select id from public.exam_papers where code = 'me-dzongkha-3'), 'standard', 12,
